/**
 * Small, dependency-free idempotency helpers for grading requests.
 *
 * The request key is generated by the client and sent with a grading request.
 * A server integration can use this key to return an already-completed result
 * instead of charging/running the same grading request twice.
 */

export const GRADING_IDEMPOTENCY_HEADER = 'x-redpen-grading-key';

export function normalizeGradingIdempotencyKey(value) {
  if (typeof value !== 'string') return null;
  const key = value.trim();
  if (!key || key.length > 128) return null;
  return /^[A-Za-z0-9._:-]+$/.test(key) ? key : null;
}

export function createGradingIdempotencyKey() {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return crypto.randomUUID();
  }

  return `grade_${Date.now()}_${Math.random().toString(36).slice(2, 12)}`;
}

/**
 * Minimal in-process completed-result cache.
 * This is deliberately bounded and only intended as an additional protection
 * for repeated requests handled by the same serverless instance. Persistent
 * idempotency must ultimately live in a transactional datastore.
 */
const completed = new Map();
const MAX_ENTRIES = 100;
const TTL_MS = 10 * 60 * 1000;

export function getCompletedGrading(key) {
  const normalized = normalizeGradingIdempotencyKey(key);
  if (!normalized) return null;

  const entry = completed.get(normalized);
  if (!entry) return null;

  if (entry.expiresAt <= Date.now()) {
    completed.delete(normalized);
    return null;
  }

  return entry.result;
}

export function rememberCompletedGrading(key, result) {
  const normalized = normalizeGradingIdempotencyKey(key);
  if (!normalized) return;

  if (completed.size >= MAX_ENTRIES) {
    const oldestKey = completed.keys().next().value;
    if (oldestKey) completed.delete(oldestKey);
  }

  completed.set(normalized, {
    result,
    expiresAt: Date.now() + TTL_MS,
  });
}
